CREATE TABLE IF NOT EXISTS gestoras(codigo_gestora TEXT PRIMARY KEY,nombre TEXT NOT NULL,activo INTEGER NOT NULL CHECK(activo IN(0,1)));
CREATE TABLE IF NOT EXISTS beneficiarios(
 codigo_beneficiario TEXT PRIMARY KEY,codigo_gestora TEXT NOT NULL REFERENCES gestoras(codigo_gestora),
 activo INTEGER CHECK(activo IN(0,1)),estado_validacion TEXT NOT NULL,qr_contenido TEXT NOT NULL UNIQUE,
 regional TEXT,operador TEXT,modalidad TEXT,escolaridad TEXT,fecha_retiro TEXT,motivo_retiro TEXT,
 consecutivo_origen INTEGER,nombre_completo TEXT,nombres TEXT,primer_nombre TEXT,apellidos TEXT,sexo TEXT,tipo_documento TEXT,documento TEXT,sim TEXT,fecha_nacimiento TEXT,edad_origen TEXT,dia_cumpleanos INTEGER,mes_cumpleanos TEXT,lugar_nacimiento TEXT,situacion_legal TEXT,resolucion TEXT,autoridad_boleta_ingreso TEXT,municipio_residencia TEXT,fecha_apertura_pard TEXT,fecha_ingreso_modalidad TEXT,motivo_ingreso TEXT,concepto_evaluacion_integradora TEXT,fecha_ingreso_hogar_actual TEXT,permanencia_hogar_origen TEXT,madre_padre_sustituto TEXT,autoridad_competente TEXT,centro_zonal TEXT,diagnostico TEXT,eps TEXT,regimen TEXT,cuenta_con_tutela TEXT,fecha_seguimiento_origen TEXT,nivel_riesgo_origen TEXT,nivel_atencion_origen TEXT,seguimientos_mensuales_origen INTEGER,fecha_reunion_origen TEXT,fecha_reunion_actualizada_origen TEXT,gestora_origen TEXT,observaciones_yo_te_cuido TEXT,
 UNIQUE(tipo_documento,documento));
CREATE TABLE IF NOT EXISTS historial_estados(id INTEGER PRIMARY KEY,codigo_beneficiario TEXT NOT NULL REFERENCES beneficiarios(codigo_beneficiario),activo_anterior INTEGER,activo_nuevo INTEGER CHECK(activo_nuevo IN(0,1)),fecha TEXT NOT NULL,motivo TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS seguimientos(id INTEGER PRIMARY KEY,codigo_beneficiario TEXT NOT NULL REFERENCES beneficiarios(codigo_beneficiario),codigo_gestora TEXT NOT NULL REFERENCES gestoras(codigo_gestora),fecha_elaboracion TEXT NOT NULL,nivel_riesgo TEXT CHECK(nivel_riesgo IN('Alto/Emergencia','Media','Bajo')),conclusiones TEXT,percepcion_beneficiario_red TEXT,fecha_envio_autoridad TEXT,estado TEXT NOT NULL DEFAULT 'borrador' CHECK(estado IN('borrador','finalizado')));
CREATE TABLE IF NOT EXISTS avances(id INTEGER PRIMARY KEY,seguimiento_id INTEGER NOT NULL REFERENCES seguimientos(id),situacion_abordada TEXT,atencion_realizada TEXT,avance_cuantitativo TEXT,avance_cualitativo TEXT,requiere_atenciones_adicionales INTEGER CHECK(requiere_atenciones_adicionales IN(0,1)));
CREATE TABLE IF NOT EXISTS nuevas_atenciones(id INTEGER PRIMARY KEY,seguimiento_id INTEGER NOT NULL REFERENCES seguimientos(id),situacion TEXT,prioridad INTEGER CHECK(prioridad IN(1,2,3)),nivel_atencion TEXT CHECK(nivel_atencion IN('I','F','S')),resultado_esperado TEXT,atencion_necesaria TEXT,responsable TEXT,fecha_limite TEXT);
CREATE TABLE IF NOT EXISTS participantes(id INTEGER PRIMARY KEY,seguimiento_id INTEGER NOT NULL REFERENCES seguimientos(id),rol_en_caso TEXT,nombre TEXT,profesion TEXT,firma_referencia TEXT);
CREATE TABLE IF NOT EXISTS entregables(id INTEGER PRIMARY KEY,seguimiento_id INTEGER NOT NULL REFERENCES seguimientos(id),formato TEXT CHECK(formato IN('pdf','csv','xlsx')),ruta TEXT,fecha_generacion TEXT);
CREATE TABLE IF NOT EXISTS fuentes(id INTEGER PRIMARY KEY,archivo TEXT,hoja TEXT,criterio TEXT);